package org.iets3.core.plugin.plugin;

/*Generated by MPS */

import org.jetbrains.mps.openapi.module.SRepository;
import javax.swing.SwingUtilities;
import com.intellij.openapi.progress.util.ProgressIndicatorBase;
import com.intellij.openapi.progress.ProgressManager;

public class CommandWithMessage {

  public static void execute(final String message, final SRepository repository, final Runnable runnable) {
    // Let the action finish and its menu close before the command blocks the UI thread.
    SwingUtilities.invokeLater(() -> {
      // The command runs on the UI thread, so the overlay is painted from a thread of its own.
      // The runnable can report its progress to ProgressManager.getInstance().getProgressIndicator().
      ProgressIndicatorBase indicator = new ProgressIndicatorBase();
      indicator.setText(message);
      Runnable inCommand = () -> repository.getModelAccess().executeCommand(() -> runnable.run());
      ProgressOverlay overlay = ProgressOverlay.start(message, indicator, repository);
      try {
        ProgressManager.getInstance().runProcess(inCommand, indicator);
      } finally {
        overlay.stop();
      }
    });
  }

}
